import{_ as a,a0 as p,w as n,s as i,ao as m,I as d,x as t,a1 as s,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Emacs 註釋中的拼寫檢查 | LCTT x X-CMD","titleTemplate":false,"description":"Emacs 註釋中的拼寫檢查 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Emacs 註釋中的拼寫檢查 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Emacs 註釋中的拼寫檢查 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190524 Spell Checking Comments","title":"Emacs 註釋中的拼寫檢查","tag":"201909","desc":""},"relativePath":"201909/20190524 Spell Checking Comments.md","filePath":"[post].md"}'),r={name:"201909/20190524 Spell Checking Comments.md"};function f(u,e,g,c,C,k){const o=p("Link");return n(),i("div",null,[e[15]||(e[15]=m('<h1 id="emacs-註釋中的拼寫檢查" tabindex="-1">Emacs 註釋中的拼寫檢查 <a class="header-anchor" href="#emacs-註釋中的拼寫檢查" aria-label="Permalink to “Emacs 註釋中的拼寫檢查”">​</a></h1><p>我出了名的容易拼錯單詞（特別是在播客當中）。謝天謝地 Emacs 內置了一個名為 <code>flyspell</code> 的超棒模式來幫助像我這樣的可憐的打字員。flyspell 會在你輸入時突出顯示拼錯的單詞 (也就是實時的) 並提供有用的快捷鍵來快速修復該錯誤。</p><p>大多輸入通常會對派生自 <code>text-mode</code>（比如 <code>markdown-mode</code>，<code>adoc-mode</code> ）的主模式啓用 <code>flyspell</code>，但是它對程序員也有所幫助，可以指出他在註釋中的錯誤。所需要的只是啓用 <code>flyspell-prog-mode</code>。我通常在所有的編程模式中（至少在 <code>prog-mode</code> 派生的模式中）都啓用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(add-hook &#39;prog-mode-hook #&#39;flyspell-prog-mode)</span></span></code></pre></div><p>現在當你在註釋中輸入錯誤時，就會得到即時反饋了。要修復單詞只需要將光標置於單詞後，然後按下 <code>C-c $</code> （<code>M-x flyspell-correct-word-before-point</code>）。（還有許多其他方法可以用 <code>flyspell</code> 來糾正拼寫錯誤的單詞，但為了簡單起見，我們暫時忽略它們。）</p><p><img src="https://emacsredux.com/assets/images/flyspell_prog_mode.gif" alt="flyspell_prog_mode.gif"></p><p>今天的分享就到這裏！我要繼續修正這些討厭的拼寫錯誤了！</p><hr>',8)),d("p",null,[e[1]||(e[1]=t("via: ",-1)),s(o,{href:"https://emacsredux.com/blog/2019/05/24/spell-checking-comments/"},{default:l(()=>[...e[0]||(e[0]=[t("https://emacsredux.com/blog/2019/05/24/spell-checking-comments/",-1)])]),_:1})]),d("p",null,[e[6]||(e[6]=t("作者：",-1)),s(o,{href:"https://emacsredux.com"},{default:l(()=>[...e[2]||(e[2]=[t("Bozhidar Batsov",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[4]||(e[4]=[t("lujun9972",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),d("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:l(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const b=a(r,[["render",f]]);export{x as __pageData,b as default};
